package pager

// Page is one window of a list, numbered from one.
type Page struct {
	Items  []string
	Number int
	Last   bool
}

const pageSize = 3

// Pages splits items into fixed-size pages.
func Pages(items []string) []Page {
	var pages []Page
	for start := 0; start < len(items); start += pageSize {
		end := start + pageSize
		if end > len(items) {
			end = len(items)
		}
		pages = append(pages, Page{Items: items[start:end], Number: len(pages) + 1, Last: start+pageSize == len(items)})
	}
	return pages
}

