package pager

import "testing"

func TestPagesOfExactMultiple(t *testing.T) {
	pages := Pages([]string{"a", "b", "c", "d", "e", "f"})
	if len(pages) != 2 || !pages[1].Last {
		t.Fatalf("pages = %+v", pages)
	}
}

